<?php require __DIR__.'/includes/bootstrap.php';$title='ASMR Creators';$creators=$pdo?$pdo->query("SELECT * FROM creators WHERE status='published' ORDER BY name")->fetchAll():[];require __DIR__.'/includes/header.php';?><div class="container"><h1>ASMR Creators</h1><p class="muted">Discover creators and visit their official channels.</p><div class="grid"><?php foreach($creators as $c):?><article class="card"><?php if($c['profile_image']):?><img loading="lazy" src="<?=e(url('uploads/'.$c['profile_image']))?>" alt="<?=e($c['name'])?>" style="max-width:100%;border-radius:12px"><?php endif;?><h2><a href="<?=url('creators/'.$c['slug'].'/')?>"><?=e($c['name'])?></a></h2><p class="muted"><?=e($c['country']??'')?> &middot; <?=e($c['language']??'')?></p><p><?=e($c['biography']??'')?></p><?php if($c['youtube_url']):?><a href="<?=e($c['youtube_url'])?>" target="_blank" rel="noopener noreferrer">Official channel</a><?php endif;?></article><?php endforeach;?></div><?php if(!$creators):?><p class="muted">No published creators are available yet.</p><?php endif;?></div><?php require __DIR__.'/includes/footer.php';


